package com.frostsecurity.extreme.network; import java.time.Instant; import java.util.*; public final class SessionHistory { public record Session(String address,Instant start,Instant end){} private final Deque<Session> sessions=new ArrayDeque<>(); public void add(Session s){sessions.addLast(s);while(sessions.size()>100)sessions.removeFirst();} public List<Session> all(){return List.copyOf(sessions);} }